import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import '@kerfjs/ui/layout.css';
import './item-dialog.css';
type Item = {id:string; name:string; summary:string; owner:string; updated:string};
export function ItemDialog({open, items, onClose, onChoose}: {open:boolean; items:Item[]; onClose:()=>void; onChoose:(id:string)=>void}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const titleId = useId(), summaryId = useId(), listName = useId();
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = items.find(item => item.id === selectedId) ?? items[0];
  useEffect(() => {
    const element = dialog.current;
    if (!element) return;
    const previous = document.activeElement as HTMLElement | null;
    if (open && !element.open) element.showModal();
    if (!open && element.open) element.close();
    return () => { if (element.open) element.close(); if (previous?.isConnected) previous.focus(); };
  }, [open]);
  return <dialog ref={dialog} className="kui-layout item-dialog" aria-labelledby={titleId} aria-describedby={summaryId} onCancel={event => {event.preventDefault(); onClose();}}>
    <DialogHeader><h2 id={titleId}>Choose an item</h2><p id={summaryId}>Select an item to review its details, then confirm your choice.</p></DialogHeader>
    <div className="dialog-content">
      <fieldset className="item-list"><legend>Available items</legend>
        {items.map(item => <label key={item.id}><input type="radio" name={listName} value={item.id} checked={selected?.id === item.id} onChange={() => setSelectedId(item.id)}/>{item.name}</label>)}
        {!items.length && <p>No items available.</p>}
      </fieldset>
      <section className="item-detail" aria-label="Selected item details" aria-live="polite">
        {selected ? <><h3>{selected.name}</h3><p>{selected.summary}</p><dl><dt>Owner</dt><dd>{selected.owner}</dd><dt>Last updated</dt><dd>{selected.updated}</dd></dl></> : <p>Add an item before choosing.</p>}
      </section>
    </div>
    <footer className="dialog-actions"><button type="button" onClick={onClose}>Cancel</button><button type="button" disabled={!selected} onClick={() => {if (selected) onChoose(selected.id);}}>Choose item</button></footer>
  </dialog>;
}

