.item-dialog { inline-size: min(52rem, calc(100% - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: auto; box-sizing: border-box; }
.item-dialog::backdrop { background: rgb(0 0 0 / 45%); }
.dialog-content { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,2fr); }
.item-list, .item-detail { min-inline-size: 0; overflow-wrap: anywhere; }
.item-list label { display: flex; align-items: center; min-block-size: 44px; }
.dialog-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; }
.dialog-actions button { min-block-size: 44px; }
.item-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
@media (max-width: 36rem) { .dialog-content { grid-template-columns: minmax(0,1fr); } }
